+        /// <summary>
+        /// 处理单个订单的可清单逻辑
+        /// </summary>
+        /// <param name="orderId">订单ID</param>
+        /// <returns></returns>
+        private async Task ProcessSingleOrderAsync(int orderId)
+        {
+            var ordr = await UnitWork.FindSingleAsync<ORDR>(x => x.DocEntry == orderId);
+            var ordrStat = await UnitWork.FindSingleAsync<OrdrStat>(x => x.Code == orderId.ToString());
+
+            // 已收全款，但是应收余额大于0自动可清单
+            if (ordrStat.U_ReceivePayStatus != 1)
+            {
+                return;
+            }
+
+            // 计算人民币余额（用于100元判断）
+            var docTotalRMB = ordr.DocTotal.Value;
+            if (docTotalRMB <= 0)
+                return;
+
+            var receiptAmountRMB = ordr.U_DocRCTAmount ?? 0M;
+            var uRefundAmtRMB = ordrStat.U_Refund_Amt;
+            decimal balanceRMB = CalculateBalanceRMB(ordr, ordrStat, docTotalRMB, receiptAmountRMB, uRefundAmtRMB);
+
+            // 计算回款率并判断是否可清单
+            decimal paymentRate = CalculatePaymentRate(ordr, ordrStat, docTotalRMB, receiptAmountRMB, uRefundAmtRMB, balanceRMB);
+
+            // 判断是否应该可清单
+            bool shouldPlugin = ordrStat.U_ReceivePayStatus == 1 ||
+                               (paymentRate >= 0.98m && Math.Abs(balanceRMB) < 100m);
+
+            if (!shouldPlugin) return;
+
+            await ProcessPluginAsync(orderId, ordr, ordrStat, docTotalRMB, balanceRMB, paymentRate);
+        }
+
+        /// <summary>
+        /// 计算人民币余额
+        /// </summary>
+        private decimal CalculateBalanceRMB(ORDR ordr, OrdrStat ordrStat, decimal docTotalRMB, decimal receiptAmountRMB, decimal uRefundAmtRMB)
+        {
+            if (ordr.DocStatus == "C")
+            {
+                return (ordrStat.U_Delivery_TotalAmt ?? 0) - (receiptAmountRMB - uRefundAmtRMB);
+            }
+            return docTotalRMB - (receiptAmountRMB - uRefundAmtRMB);
+        }
+
+        /// <summary>
+        /// 计算回款率
+        /// </summary>
+        private decimal CalculatePaymentRate(ORDR ordr, OrdrStat ordrStat, decimal docTotalRMB, decimal receiptAmountRMB, decimal uRefundAmtRMB, decimal balanceRMB)
+        {
+            decimal paymentRate;
+            if (ordr.DocCur == FinanceConsts.RMB)
+            {
+                paymentRate = (receiptAmountRMB - uRefundAmtRMB) / docTotalRMB;
+                if (balanceRMB <= 0)
+                {
+                    return -1; // 标记为无效
+                }
+            }
+            else
+            {
+                var docTotalFC = ordr.DocTotalFC.Value;
+                var receiptAmountFC = ordrStat.U_Receipt_TotalAmtFC ?? 0M;
+                var uRefundAmtFC = ordrStat.U_Refund_AmtFC;
+                if (docTotalFC <= 0)
+                    return -1;
+                if (docTotalFC - (receiptAmountFC - uRefundAmtFC) <= 0)
+                {
+                    return -1;
+                }
+                paymentRate = (receiptAmountFC - uRefundAmtFC) / docTotalFC;
+            }
+            return paymentRate;
+        }
+
